from collections import deque

def resolve(path, cwd, links):
    def parent(cur):
        if cur == '/':
            return '/'
        idx = cur.rfind('/')
        if idx <= 0:
            return '/'
        return cur[:idx]

    def join(cur, name):
        if cur == '/':
            return '/' + name
        return cur + '/' + name

    if path.startswith('/'):
        current = '/'
    else:
        current = cwd

    queue = deque(path.split('/'))
    link_count = 0

    while queue:
        comp = queue.popleft()
        if comp == '' or comp == '.':
            continue
        elif comp == '..':
            current = parent(current)
        else:
            candidate = join(current, comp)
            if candidate in links:
                link_count += 1
                if link_count > 8:
                    return None
                target = links[candidate]
                if target.startswith('/'):
                    # prepend target components, current unchanged
                    target_parts = target.split('/')
                    queue = deque(target_parts) + queue
                    # need current reset to '/' since target absolute
                    current = '/'
                else:
                    target_parts = target.split('/')
                    queue = deque(target_parts) + queue
                    # current stays the directory containing the link
            else:
                current = candidate

    return current

